<template>
  <PageContainer title="查看全部对话" description="继续、搜索和管理所有和 Mira 的会话。">
    <template #actions><el-button type="primary" @click="newSession"><AppIcon name="Plus" />新对话</el-button></template>

    <section class="history-stats" aria-label="会话数据摘要">
      <article v-for="card in statCards" :key="card.label" class="history-stat" :class="`history-stat--${card.tone}`"><span>{{ card.label }}</span><strong>{{ card.value }}</strong><small>{{ card.hint }}</small></article>
    </section>

    <section class="history-toolbar" aria-label="对话筛选与排序">
      <el-input v-model="query" clearable class="history-search" placeholder="搜索对话标题、模型或项目" aria-label="搜索对话"><template #prefix><AppIcon name="Search" /></template></el-input>
      <el-select v-model="projectIds" multiple collapse-tags collapse-tags-tooltip class="history-select" placeholder="项目" aria-label="筛选项目"><el-option label="临时对话" value="__temporary__" /><el-option v-for="project in facets.projects" :key="project.id" :label="project.name" :value="project.id" /></el-select>
      <el-select v-model="modelIds" multiple collapse-tags collapse-tags-tooltip class="history-select" placeholder="模型" aria-label="筛选模型"><el-option v-for="model in facets.models" :key="model.id" :label="model.id" :value="model.id" /></el-select>
      <el-select v-model="statuses" multiple collapse-tags collapse-tags-tooltip class="history-select history-select--status" placeholder="状态" aria-label="筛选状态"><el-option label="进行中" value="active" /><el-option label="完成" value="completed" /><el-option label="失败" value="failed" /></el-select>
      <el-select v-model="archiveView" class="history-select history-select--archive" aria-label="筛选归档状态"><el-option label="未归档" value="visible" /><el-option label="已归档" value="archived" /></el-select>
      <el-radio-group v-model="range" class="history-range" aria-label="筛选时间范围"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="today">今天</el-radio-button><el-radio-button value="week">本周</el-radio-button><el-radio-button value="month">本月</el-radio-button></el-radio-group>
      <el-select v-model="sort" class="history-sort" aria-label="排序方式"><el-option label="最近活动" value="updated-desc" /><el-option label="创建时间" value="created-desc" /><el-option label="标题 A-Z" value="title-asc" /></el-select>
      <el-radio-group v-model="density" class="history-density" aria-label="列表密度"><el-tooltip content="舒适密度"><el-radio-button value="comfortable" aria-label="舒适密度"><AppIcon name="List" /></el-radio-button></el-tooltip><el-tooltip content="紧凑密度"><el-radio-button value="compact" aria-label="紧凑密度"><AppIcon name="Menu" /></el-radio-button></el-tooltip></el-radio-group>
    </section>

    <div v-if="activeFilters.length" class="history-filters" aria-label="已应用筛选"><span>已应用筛选：</span><button v-for="filter in activeFilters" :key="filter.key" type="button" class="history-chip" @click="filter.clear">{{ filter.label }}<AppIcon name="Close" /></button><el-button link type="primary" @click="clearFilters">清除全部</el-button></div>
    <p v-if="!loading && page" class="history-result-count">显示 {{ page.rows.length }} 条，共 {{ page.total }} 条匹配会话</p>

    <section v-if="loading" class="history-list history-list--skeleton" aria-label="正在加载会话"><div v-for="item in 6" :key="item" class="history-skeleton"><el-skeleton animated :rows="1" /></div></section>
    <section v-else-if="error" class="history-error" role="alert"><AppIcon name="Warning" /><span>{{ error }}</span><el-button size="small" @click="load">重试</el-button></section>
    <section v-else-if="page?.rows.length" class="history-list" :class="`is-${density}`" role="grid" aria-label="会话列表">
      <div class="history-list__head" role="row"><span></span><span>会话</span><span class="history-column--project">项目</span><span class="history-column--model">模型</span><span>状态</span><span>时间</span><span></span></div>
      <template v-for="group in groups" :key="group.key">
        <header class="history-group"><i></i><strong>{{ group.label }}</strong><span>{{ group.rows.length }} 条</span></header>
        <article v-for="row in group.rows" :key="row.id" class="history-row" :class="{ 'is-selected': selectedIds.includes(row.id) }" role="row" tabindex="0" @click="open(row.id)" @keydown.enter="open(row.id)">
          <el-checkbox :model-value="selectedIds.includes(row.id)" :aria-label="`选择 ${row.title}`" @click.stop @update:model-value="toggleSelected(row.id, $event)" />
          <div class="history-title"><span class="history-avatar"><AppIcon :name="row.projectIcon || 'ChatDotRound'" /></span><span class="history-title__copy"><strong :title="row.title">{{ row.title }}</strong><small v-if="row.preview">{{ row.preview }}</small></span></div>
          <span class="history-project history-column--project">{{ row.projectName || '临时对话' }}</span><span class="history-model history-column--model"><i :class="providerClass(row.providerKey)"></i>{{ row.modelId || '默认模型' }}</span><span class="history-status" :class="`is-${row.status}`"><i></i>{{ statusLabel(row.status) }}</span><time :datetime="new Date(row.updatedAt).toISOString()">{{ formatTime(row.updatedAt) }}</time>
          <el-dropdown trigger="click" @command="handleAction"><el-button text circle aria-label="更多会话操作" @click.stop><AppIcon name="MoreFilled" /></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :command="{ action: 'open', row }"><AppIcon name="FolderOpened" />打开</el-dropdown-item><el-dropdown-item :command="{ action: 'rename', row }"><AppIcon name="EditPen" />重命名</el-dropdown-item><el-dropdown-item :command="{ action: row.archivedAt ? 'restore' : 'archive', row }"><AppIcon :name="row.archivedAt ? 'RefreshLeft' : 'Box'" />{{ row.archivedAt ? '恢复' : '归档' }}</el-dropdown-item><el-dropdown-item divided class="history-delete-menu" :command="{ action: 'delete', row }"><AppIcon name="Delete" />删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
        </article>
      </template>
    </section>
    <el-empty v-else-if="!loading" class="history-empty" :description="hasFilters ? '还没有匹配的对话' : archiveView === 'archived' ? '还没有归档的对话' : '还没有任何对话'"><template #image><AppIcon :name="hasFilters ? 'Search' : 'ChatDotRound'" /></template><p>{{ hasFilters ? '试试调整筛选条件，或清除筛选重新浏览。' : '和 Mira 聊聊你最近的想法。' }}</p><el-button v-if="hasFilters" @click="clearFilters">清除全部筛选</el-button><el-button v-else type="primary" @click="newSession"><AppIcon name="Plus" />开始新对话</el-button></el-empty>

    <footer v-if="page && page.total" class="history-pagination"><span>显示 {{ pageStart }} - {{ pageEnd }} 条，共 {{ page.total }} 条</span><el-pagination background layout="prev, pager, next" :current-page="page.page" :page-size="page.pageSize" :total="page.total" @current-change="setPage" /></footer>
    <transition name="history-bulk"><aside v-if="selectedIds.length" class="history-bulk" aria-live="polite"><strong>已选择 {{ selectedIds.length }} 项</strong><span></span><el-button @click="archiveOrRestoreSelected">{{ archiveView === 'archived' ? '批量恢复' : '批量归档' }}</el-button><el-button type="danger" plain @click="confirmDelete(selectedIds)">批量删除</el-button><el-button text @click="selectedIds = []">取消选择</el-button></aside></transition>
  </PageContainer>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import type { LocationQueryRaw } from 'vue-router'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageContainer from '@/components/PageContainer/index.vue'
import { getPreference, getPlatformApi, savePreference } from '@/platform'
import type { HarnessHistoryArchiveView, HarnessHistoryPage, HarnessHistoryRange, HarnessHistoryRow, HarnessHistorySort, HarnessSessionStatus, ModelProviderKey } from '@/config/harness'
import { useHarnessStore } from '@/stores/harness'
import { groupHistoryRows, smartRelative } from './historyUtils'

type Density = 'comfortable' | 'compact'
type Action = 'open' | 'rename' | 'archive' | 'restore' | 'delete'
const route = useRoute(); const router = useRouter(); const store = useHarnessStore()
const page = ref<HarnessHistoryPage>(); const loading = ref(false); const error = ref(''); const query = ref(''); const projectIds = ref<string[]>([]); const modelIds = ref<string[]>([]); const statuses = ref<HarnessSessionStatus[]>([]); const range = ref<HarnessHistoryRange>('all'); const archiveView = ref<HarnessHistoryArchiveView>('visible'); const sort = ref<HarnessHistorySort>('updated-desc'); const currentPage = ref(1); const selectedIds = ref<string[]>([]); const density = ref<Density>(getPreference<Density>('historyDensity', 'comfortable') === 'compact' ? 'compact' : 'comfortable'); const clock = ref(Date.now())
let hydratingRoute = false; let searchTimer: ReturnType<typeof setTimeout> | undefined; let clockTimer: ReturnType<typeof setInterval> | undefined
const facets = computed(() => page.value?.facets || { projects: [], models: [] })
const groups = computed(() => groupHistoryRows(page.value?.rows || [], clock.value))
const hasFilters = computed(() => projectIds.value.length > 0 || modelIds.value.length > 0 || statuses.value.length > 0 || range.value !== 'all' || archiveView.value === 'archived')
const pageStart = computed(() => page.value ? Math.min(page.value.total, (page.value.page - 1) * page.value.pageSize + 1) : 0)
const pageEnd = computed(() => page.value ? Math.min(page.value.total, page.value.page * page.value.pageSize) : 0)
const statCards = computed(() => { const stats = page.value?.stats; return [{ label: '对话总数', value: stats?.total ?? '—', hint: archiveView.value === 'archived' ? '已归档会话' : '当前筛选范围', tone: 'primary' }, { label: '今日新建', value: stats?.todayNew ?? '—', hint: stats ? `${stats.todayNewDelta >= 0 ? '+' : ''}${stats.todayNewDelta} 较昨日` : '—', tone: 'success' }, { label: '进行中', value: stats?.activeCount ?? '—', hint: stats?.activeStaleCount ? `${stats.activeStaleCount} 个超过 1 小时未响应` : '当前筛选范围内', tone: 'warning' }, { label: '最常使用模型', value: stats?.topModel?.id || '—', hint: stats?.topModel ? `${stats.topModel.count} 次 · ${Math.round(stats.topModel.ratio * 100)}%` : '暂无数据', tone: 'info' }] })
const activeFilters = computed(() => [
  ...projectIds.value.map(id => ({ key: `project-${id}`, label: `项目：${id === '__temporary__' ? '临时对话' : facets.value.projects.find(project => project.id === id)?.name || id}`, clear: () => projectIds.value = projectIds.value.filter(value => value !== id) })),
  ...modelIds.value.map(id => ({ key: `model-${id}`, label: `模型：${id}`, clear: () => modelIds.value = modelIds.value.filter(value => value !== id) })),
  ...statuses.value.map(status => ({ key: `status-${status}`, label: `状态：${statusLabel(status)}`, clear: () => statuses.value = statuses.value.filter(value => value !== status) })),
  ...(range.value === 'all' ? [] : [{ key: 'range', label: `时间：${rangeLabel(range.value)}`, clear: () => range.value = 'all' }]),
  ...(archiveView.value === 'visible' ? [] : [{ key: 'archive', label: '范围：已归档', clear: () => archiveView.value = 'visible' }]),
])
function readList(value: unknown) { return typeof value === 'string' ? value.split(',').filter(Boolean) : [] }
function statusLabel(status: HarnessSessionStatus) { return status === 'active' ? '进行中' : status === 'failed' ? '失败' : '完成' }
function rangeLabel(value: HarnessHistoryRange) { return value === 'today' ? '今天' : value === 'week' ? '本周' : value === 'month' ? '本月' : '全部' }
function providerClass(key?: ModelProviderKey) { return `provider-dot provider-dot--${key || 'custom'}` }
function formatTime(value: number) { return smartRelative(value, clock.value) }
function buildRouteQuery(): LocationQueryRaw { return { ...(query.value.trim() ? { q: query.value.trim() } : {}), ...(projectIds.value.length ? { project: projectIds.value.join(',') } : {}), ...(modelIds.value.length ? { model: modelIds.value.join(',') } : {}), ...(statuses.value.length ? { status: statuses.value.join(',') } : {}), ...(range.value !== 'all' ? { range: range.value } : {}), ...(archiveView.value === 'archived' ? { archive: 'archived' } : {}), ...(sort.value !== 'updated-desc' ? { sort: sort.value } : {}), ...(currentPage.value > 1 ? { page: String(currentPage.value) } : {}) } }
function hydrateFromRoute() { const value = route.query; hydratingRoute = true; query.value = typeof value.q === 'string' ? value.q : ''; projectIds.value = readList(value.project); modelIds.value = readList(value.model); statuses.value = readList(value.status).filter((item): item is HarnessSessionStatus => ['active', 'completed', 'failed'].includes(item)); range.value = ['today', 'week', 'month'].includes(value.range as string) ? value.range as HarnessHistoryRange : 'all'; archiveView.value = value.archive === 'archived' ? 'archived' : 'visible'; sort.value = ['created-desc', 'title-asc'].includes(value.sort as string) ? value.sort as HarnessHistorySort : 'updated-desc'; currentPage.value = Math.max(1, Number(value.page) || 1); void nextTick(() => { hydratingRoute = false }) }
async function syncRoute() { if (!hydratingRoute) await router.replace({ query: buildRouteQuery() }) }
async function load() { const api = getPlatformApi(); if (!api) return; loading.value = true; error.value = ''; try { page.value = await api.queryHarnessHistory({ q: query.value, projectIds: [...projectIds.value], modelIds: [...modelIds.value], statuses: [...statuses.value], range: range.value, archiveView: archiveView.value, sort: sort.value, page: currentPage.value, pageSize: 20 }); if (page.value.page !== currentPage.value) { currentPage.value = page.value.page; void syncRoute() } selectedIds.value = selectedIds.value.filter(id => page.value?.rows.some(row => row.id === id)) } catch (cause) { error.value = cause instanceof Error ? cause.message : '拉取会话失败' } finally { loading.value = false } }
function scheduleSearch() { if (searchTimer) clearTimeout(searchTimer); searchTimer = setTimeout(() => { currentPage.value = 1; void syncRoute() }, 200) }
function setPage(value: number) { currentPage.value = value; void syncRoute() }
function clearFilters() { projectIds.value = []; modelIds.value = []; statuses.value = []; range.value = 'all'; archiveView.value = 'visible'; currentPage.value = 1 }
function toggleSelected(id: string, checked: boolean | string | number) { selectedIds.value = checked ? [...new Set([...selectedIds.value, id])] : selectedIds.value.filter(value => value !== id) }
async function newSession() { const draft = store.startDraft(); await router.push({ path: '/workspace/chat', query: { draft } }) }
function open(id: string) { void router.push(`/workspace/chat/${id}`) }
async function rename(row: HarnessHistoryRow) { try { const { value } = await ElMessageBox.prompt('输入新的会话名称', '重命名会话', { inputValue: row.title, inputValidator: value => value.trim() ? true : '会话名称不能为空', confirmButtonText: '保存', cancelButtonText: '取消' }); await getPlatformApi()?.renameHarnessSession(row.id, value); ElMessage.success('会话已重命名'); await load() } catch { /* user cancelled */ } }
async function moveArchive(ids: string[], restore = false) { const api = getPlatformApi(); if (!api || !ids.length) return; const sessionIds = [...ids]; const previous = page.value; page.value = previous ? { ...previous, rows: previous.rows.filter(row => !sessionIds.includes(row.id)), total: Math.max(0, previous.total - sessionIds.length) } : previous; try { if (restore) await api.restoreHarnessSessions(sessionIds); else await api.archiveHarnessSessions(sessionIds); selectedIds.value = []; ElMessage.success(restore ? `已恢复 ${sessionIds.length} 个会话` : `已归档 ${sessionIds.length} 个会话`); await load() } catch (cause) { page.value = previous; ElMessage.error(cause instanceof Error ? cause.message : '操作失败') } }
async function confirmDelete(ids: string[]) { const api = getPlatformApi(); if (!api || !ids.length) return; const sessionIds = [...ids]; try { await ElMessageBox.confirm(sessionIds.length === 1 ? '删除后无法恢复该会话。' : `将删除 ${sessionIds.length} 个会话，且无法恢复。`, sessionIds.length === 1 ? '删除会话' : '批量删除会话', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }) } catch { return } const previous = page.value; page.value = previous ? { ...previous, rows: previous.rows.filter(row => !sessionIds.includes(row.id)), total: Math.max(0, previous.total - sessionIds.length) } : previous; try { await api.deleteHarnessSessions(sessionIds); selectedIds.value = []; ElMessage.success(`已删除 ${sessionIds.length} 个会话`); await load() } catch (cause) { page.value = previous; ElMessage.error(cause instanceof Error ? cause.message : '删除失败') } }
function archiveOrRestoreSelected() { void moveArchive(selectedIds.value, archiveView.value === 'archived') }
function handleAction(command: { action: Action, row: HarnessHistoryRow }) { if (command.action === 'open') open(command.row.id); else if (command.action === 'rename') void rename(command.row); else if (command.action === 'delete') void confirmDelete([command.row.id]); else void moveArchive([command.row.id], command.action === 'restore') }

watch(() => route.query, () => { hydrateFromRoute(); void load() }, { immediate: true, deep: true })
watch(query, () => { if (!hydratingRoute) scheduleSearch() })
watch([projectIds, modelIds, statuses, range, archiveView, sort], () => { if (!hydratingRoute) { currentPage.value = 1; void syncRoute() } }, { deep: true })
watch(density, value => savePreference('historyDensity', value))
onMounted(() => { clockTimer = setInterval(() => clock.value = Date.now(), 60_000) })
onUnmounted(() => { if (searchTimer) clearTimeout(searchTimer); if (clockTimer) clearInterval(clockTimer) })
</script>

<style scoped lang="scss">
.history-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: $spacing-md; margin-bottom: $spacing-lg; }.history-stat { position: relative; min-width: 0; min-height: 88px; padding: 16px; overflow: hidden; border: 1px solid var(--cp-border); border-radius: $radius-md; background: var(--cp-bg-elevated); }.history-stat::after { position: absolute; top: 12px; right: 0; bottom: 12px; width: 3px; border-radius: 3px 0 0 3px; background: var(--cp-primary); content: ''; }.history-stat--success::after { background: var(--cp-success); }.history-stat--warning::after { background: var(--cp-warning); }.history-stat--info::after { background: var(--cp-info); }.history-stat > span, .history-stat > small { display: block; overflow: hidden; color: var(--cp-text-secondary); font-size: $font-xs; text-overflow: ellipsis; white-space: nowrap; }.history-stat > strong { display: block; margin: 5px 0; overflow: hidden; color: var(--cp-text); font-size: 24px; font-weight: $font-semibold; line-height: 1; text-overflow: ellipsis; white-space: nowrap; }.history-stat--info > strong { font-size: 17px; line-height: 1.35; }
.history-toolbar { display: flex; align-items: center; gap: $spacing-sm; margin-bottom: $spacing-sm; flex-wrap: wrap; }.history-search { width: min(100%, 350px); margin-right: auto; }.history-select { width: 126px; }.history-select--status { width: 118px; }.history-select--archive, .history-sort { width: 128px; }.history-range { flex-shrink: 0; }.history-range :deep(.el-radio-button__inner), .history-density :deep(.el-radio-button__inner) { padding: 8px 9px; }.history-density { flex-shrink: 0; }.history-filters { display: flex; align-items: center; min-height: 36px; gap: 7px; margin-bottom: $spacing-sm; flex-wrap: wrap; color: var(--cp-text-secondary); font-size: $font-xs; }.history-chip { display: inline-flex; align-items: center; gap: 4px; max-width: 220px; padding: 4px 7px; overflow: hidden; border: 1px solid var(--cp-primary-light); border-radius: 999px; color: var(--cp-primary); background: var(--cp-primary-lighter); font: inherit; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }.history-chip .app-icon { font-size: 12px; }.history-result-count { margin: 0 0 $spacing-sm; color: var(--cp-text-tertiary); font-size: $font-xs; }
.history-list { overflow: hidden; border: 1px solid var(--cp-border); border-radius: $radius-md; background: var(--cp-bg); }.history-list__head, .history-row { display: grid; grid-template-columns: 32px minmax(210px, 1.7fr) minmax(110px, .75fr) minmax(130px, .9fr) 90px 120px 40px; gap: 10px; min-width: 760px; align-items: center; padding: 0 14px; }.history-list__head { height: 38px; color: var(--cp-text-tertiary); background: var(--cp-bg-elevated); font-size: $font-xs; font-weight: $font-semibold; }.history-group { position: sticky; top: 0; z-index: 1; display: flex; align-items: center; gap: 7px; height: 42px; padding: 0 14px; border-top: 1px solid var(--cp-border-light); border-bottom: 1px solid var(--cp-border-light); color: var(--cp-text-secondary); background: var(--cp-bg-elevated); font-size: $font-sm; }.history-group i { width: 3px; height: 14px; border-radius: 3px; background: var(--cp-text-tertiary); }.history-group span { color: var(--cp-text-tertiary); font-size: $font-xs; }.history-row { min-height: 64px; border-bottom: 1px solid var(--cp-border-light); color: var(--cp-text-secondary); font-size: $font-sm; cursor: pointer; outline: none; transition: background-color $transition-fast; }.history-row:last-child { border-bottom: 0; }.history-row:hover, .history-row:focus-visible { background: var(--cp-bg-hover); }.history-row.is-selected { background: var(--cp-primary-lighter); }.history-list.is-compact .history-row { min-height: 48px; }.history-list.is-compact .history-title__copy small { display: none; }.history-title { display: flex; min-width: 0; align-items: center; gap: 9px; }.history-avatar { display: grid; width: 30px; height: 30px; flex: 0 0 auto; place-items: center; border-radius: $radius-sm; color: var(--cp-primary); background: var(--cp-primary-lighter); }.history-title__copy { display: flex; min-width: 0; flex-direction: column; gap: 3px; }.history-title__copy strong, .history-title__copy small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.history-title__copy strong { color: var(--cp-text); font-weight: $font-semibold; }.history-title__copy small { color: var(--cp-text-secondary); font-size: $font-xs; }.history-project { display: inline-flex; width: fit-content; max-width: 100%; padding: 3px 7px; overflow: hidden; border-radius: 999px; color: var(--cp-text-secondary); background: var(--cp-bg-hover); font-size: $font-xs; text-overflow: ellipsis; white-space: nowrap; }.history-model, .history-status { display: inline-flex; min-width: 0; align-items: center; gap: 6px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.provider-dot, .history-status i { width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--cp-text-tertiary); }.provider-dot--deepseek { background: var(--cp-primary); }.provider-dot--glm, .provider-dot--kimi { background: var(--cp-success); }.provider-dot--minimax { background: var(--cp-warning); }.history-status.is-completed i { background: var(--cp-success); }.history-status.is-active { color: var(--cp-primary); }.history-status.is-active i { background: var(--cp-primary); box-shadow: 0 0 0 3px var(--cp-primary-light); }.history-status.is-failed { color: var(--cp-danger); }.history-status.is-failed i { background: var(--cp-danger); }.history-row time { color: var(--cp-text-tertiary); font-size: $font-xs; }.history-error { display: flex; align-items: center; gap: 8px; padding: 12px; border: 1px solid var(--cp-danger-light); border-radius: $radius-md; color: var(--cp-danger); background: color-mix(in srgb, var(--cp-danger) 7%, var(--cp-bg)); }.history-error .el-button { margin-left: auto; }.history-list--skeleton { padding: 0 16px; }.history-skeleton { padding: 17px 0; border-bottom: 1px solid var(--cp-border-light); }.history-empty { min-height: 300px; }.history-empty :deep(.el-empty__image) { display: grid; width: 72px; height: 72px; place-items: center; border-radius: 50%; color: var(--cp-primary); background: var(--cp-primary-light